func TestRegisterAndVerifyEmail(t *testing.T) {
	e := newTestEnv(t)
	u := e.register("Ada@Example.com")
	if u.Email != "ada@example.com" || u.EmailVerified {
		t.Fatalf("%+v", u)
	}
	tok := e.mailedToken("verification", "ada@example.com")
	e.c.POST("/auth/email/verify").JSON(map[string]string{"token": tok}).Do().ExpectStatus(http.StatusNoContent)
	// Checklist: verify tokens are single use.
	e.c.POST("/auth/email/verify").JSON(map[string]string{"token": tok}).Do().ExpectProblem(http.StatusBadRequest, "invalid_token")
	e.as(u).GET("/auth/me").Do().ExpectStatus(http.StatusOK).ExpectJSON(map[string]any{"email": "ada@example.com", "email_verified": true})
}

