var requestID = regexp.MustCompile(`,?"request_id":"[^"]*"`)

func stripRequestID(b []byte) string { return requestID.ReplaceAllString(string(b), "") }

func TestLoginLockout(t *testing.T) {
	e := newTestEnv(t)
	u := e.register("lock@x.io")
	for range 5 {
		e.login("lock@x.io", "wrong-password-123", "").ExpectProblem(http.StatusUnauthorized, "invalid_credentials")
	}
	// Locked: even the right password gets the same generic answer.
	e.login("lock@x.io", strongPassword, "").ExpectProblem(http.StatusUnauthorized, "invalid_credentials")
	locked, _ := e.st.UserByID(context.Background(), u.ID)
	if locked.lockedUntil == nil || time.Until(*locked.lockedUntil) < 50*time.Second {
		t.Fatalf("locked_until = %v", locked.lockedUntil)
	}
	_ = e.st.LockUser(context.Background(), u.ID, time.Now().Add(-time.Second))
	e.login("lock@x.io", strongPassword, "").ExpectStatus(http.StatusOK)
	if after, _ := e.st.UserByID(context.Background(), u.ID); after.failedLogins != 0 {
		t.Errorf("failed_logins not reset: %d", after.failedLogins)
	}
}

