func TestResetTokenExpires(t *testing.T) {
	e := newTestEnv(t)
	u := e.register("old@x.io")
	tok, err := e.h.svc.newAuthToken(context.Background(), u.ID, "reset", -time.Minute)
	if err != nil {
		t.Fatal(err)
	}
	e.c.POST("/auth/password/reset").JSON(map[string]string{"token": tok, "password": "a-brand-new-passphrase"}).Do().
		ExpectProblem(http.StatusBadRequest, "invalid_token")
	// A verify token cannot be used as a reset token.
	verify := e.mailedToken("verification", "old@x.io")
	e.c.POST("/auth/password/reset").JSON(map[string]string{"token": verify, "password": "a-brand-new-passphrase"}).Do().
		ExpectProblem(http.StatusBadRequest, "invalid_token")
}

